begin
 if new.content_key<>'goodies.content' or new.status<>'published' then return new;end if;
 if tg_op='UPDATE' and old.status='published' and
   (new.payload-array['fees']) is not distinct from (old.payload-array['fees']) then return new;end if;
 for v_entry in select value from jsonb_array_elements(coalesce(new.payload->'labels','[]'::jsonb)) loop
  if v_entry->>'id'=any(v_critical) then perform private.goodies_assert_reviewed_text(v_entry->'t');end if;
 end loop;
 for v_entry in select value from jsonb_array_elements(coalesce(new.payload->'faq','[]'::jsonb)) loop
  if v_entry->'a'->'en'->>'v' ~* '^\s*answer coming soon[.!]?\s*$' then
   raise exception 'Replace placeholder Goodies FAQ answers before publishing' using errcode='22023';end if;
  perform private.goodies_assert_reviewed_text(v_entry->'q');perform private.goodies_assert_reviewed_text(v_entry->'a');
 end loop;
 for v_key in select unnest(array['legal','topics']) loop
  for v_entry in select value from jsonb_array_elements(coalesce(new.payload->v_key,'[]'::jsonb)) loop
   if v_key<>'legal' or v_entry->>'st'='Live' then perform private.goodies_assert_reviewed_text(v_entry->'t');end if;
  end loop;
 end loop;
 for v_entry in select value from jsonb_array_elements(coalesce(new.payload->'rg'->'texts','[]'::jsonb)) loop
  perform private.goodies_assert_reviewed_text(v_entry->'t');
 end loop;
 return new;
end $$;
revoke all on function private.goodies_guard_content_publication() from public,anon,authenticated;
commit;
